175			public Object adaptReactiveResult(
176					MethodInvocation invocation, Object result, ReactiveAdapter adapter, MethodRetrySpec spec) {
177	
178				Publisher<?> publisher = adapter.toPublisher(result);
179				Retry retry = Retry.backoff(spec.maxRetries(), spec.delay())
180						.jitter(calculateJitterFactor(spec))
181						.multiplier(spec.multiplier())
182						.maxBackoff(spec.maxDelay())
183						.filter(spec.combinedPredicate().forMethod(invocation.getMethod()));
184	
185				Duration timeout = spec.timeout();
186				boolean timeoutIsPositive = (!timeout.isNegative() && !timeout.isZero());
187				if (adapter.isMultiValue()) {
188					Flux<?> flux = Flux.from(publisher)
189							.doOnError(ex -> onEvent(new MethodRetryEvent(invocation, ex, false)))
190							.retryWhen(retry);
191					if (timeoutIsPositive) {
192						flux = flux.timeout(timeout);
193					}
194					flux = flux.doOnError(ex -> onEvent(new MethodRetryEvent(invocation, ex, true)));
195					publisher = flux;
196				}
197				else {
198					Mono<?> mono = Mono.from(publisher)
199							.doOnError(ex -> onEvent(new MethodRetryEvent(invocation, ex, false)))
200							.retryWhen(retry);
201					if (timeoutIsPositive) {
202						mono = mono.timeout(timeout);
203					}
204					mono = mono.doOnError(ex -> onEvent(new MethodRetryEvent(invocation, ex, true)));
205					publisher = mono;
206				}
207	
208				return adapter.fromPublisher(publisher);
209			}
