211			private static double calculateJitterFactor(MethodRetrySpec spec) {
212				return (spec.delay().isZero() ? 0.0 :
213						Math.max(0.0, Math.min(1.0, spec.jitter().toNanos() / (double) spec.delay().toNanos())));
