280	
281			private long currentInterval = -1;
282	
283			private long currentElapsedTime = 0;
284	
285			private int attempts = 0;
286	
287			@Override
288			public long nextBackOff() {
289				if (this.currentElapsedTime >= getMaxElapsedTime() || this.attempts >= getMaxAttempts()) {
290					return STOP;
291				}
292				long nextInterval = computeNextInterval();
293				this.currentElapsedTime += nextInterval;
294				this.attempts++;
295				return nextInterval;
296			}
297	
298			private long computeNextInterval() {
299				long maxInterval = getMaxInterval();
300				long nextInterval;
301				if (this.currentInterval < 0) {
302					nextInterval = getInitialInterval();
303				}
304				else if (this.currentInterval >= maxInterval) {
305					nextInterval = maxInterval;
306				}
307				else {
308					nextInterval = Math.min((long) (this.currentInterval * getMultiplier()), maxInterval);
309				}
310				this.currentInterval = nextInterval;
311				return Math.min(applyJitter(nextInterval), maxInterval);
312			}
313	
314			private long applyJitter(long interval) {
315				long jitter = getJitter();
316				if (jitter > 0) {
317					long initialInterval = getInitialInterval();
318					// When initialInterval is 0 the interval never grows, so the scale factor
319					// stays at its baseline value of 1 and the full configured jitter is applied.
320					long applicableJitter = jitter * (initialInterval > 0 ? (interval / initialInterval) : 1);
321					long min = Math.max(interval - applicableJitter, initialInterval);
322					long max = Math.min(interval + applicableJitter, getMaxInterval());
323					return min + (long) (Math.random() * (max - min));
324				}
325				return interval;
326			}
